"""Bahasa Indonesia — akidah dan ibadah (faith_001 … faith_070)."""

T = {
"faith_001": ("Berapa jumlah rukun Islam?", ["5", "4", "6", "7"], "Hadis Jibril dan hadis yang diriwayatkan Ibnu Umar menyebutkan lima rukun Islam."),
"faith_002": ("Apa nama pernyataan keimanan dalam Islam?", ["Syahadat", "Salat", "Zakat", "Haji"], "Syahadat, kesaksian iman, adalah rukun Islam yang pertama."),
"faith_003": ("Berapa kali sehari salat wajib dilaksanakan dalam Islam?", ["5", "3", "4", "7"], "Lima salat wajib sehari-hari adalah rukun dasar Islam."),
"faith_004": ("Apa nama sedekah wajib dalam Islam?", ["Zakat", "Sedekah", "Wakaf", "Kafarat"], "Zakat adalah sedekah wajib, salah satu dari lima rukun Islam."),
"faith_005": ("Apa nama bulan puasa wajib dalam Islam?", ["Ramadan", "Syawal", "Rajab", "Muharam"], "Al-Qur'an memerintahkan puasa selama bulan Ramadan."),
"faith_006": ("Apa nama ibadah ke Makkah yang wajib sekali seumur hidup bagi yang mampu?", ["Haji", "Umrah", "Iktikaf", "Tawaf"], "Al-Qur'an mewajibkan haji, setidaknya sekali seumur hidup, bagi siapa pun yang mampu melaksanakannya."),
"faith_007": ("Ke arah mana umat Islam menghadap saat salat?", ["Ka'bah, di Makkah", "Yerusalem", "Madinah", "Timur"], "Al-Qur'an menetapkan Ka'bah sebagai arah salat (kiblat)."),
"faith_008": ("Menurut hadis yang terkenal, berapa jumlah rukun iman yang umum diajarkan?", ["6", "4", "5", "7"], "Hadis Jibril menyebutkan enam rukun iman: Allah, para malaikat, kitab-kitab, para rasul, hari Akhir, dan takdir."),
"faith_009": ("Apa nama bersuci dengan air yang dilakukan seorang Muslim sebelum setiap salat?", ["Wudu", "Tayamum", "Mandi besar", "Siwak"], "«Apabila kamu hendak melaksanakan salat, maka basuhlah wajahmu dan tanganmu…»: inilah wudu."),
"faith_010": ("Menurut Al-Qur'an, apa yang dilakukan «para pencatat yang mulia» (kiraman katibin)?", ["Mencatat amal perbuatan manusia", "Memikul Arasy", "Menjaga surga", "Menurunkan hujan"], "«Padahal sesungguhnya bagi kamu ada malaikat-malaikat yang mengawasi, yang mulia dan mencatat»: para malaikat mencatat setiap amal."),
"faith_011": ("Berapa jumlah nama-nama indah Allah yang disebutkan dalam riwayat sahih?", ["99", "50", "100", "114"], "Hadis sahih yang diriwayatkan al-Bukhari dan Muslim menyebutkan sembilan puluh sembilan nama, seratus kurang satu."),
"faith_012": ("Apa arti nama Allah «Ar-Rahman»?", ["Yang Maha Pengasih", "Yang Maha Pencipta", "Yang Maha Merajai", "Yang Maha Mengetahui"], "Ar-Rahman, Yang Maha Pengasih: rahmat-Nya meliputi segala sesuatu."),
"faith_013": ("Dalam Al-Fatihah, Allah disebut «Pemilik» hari apa?", ["Hari Pembalasan", "Hari Jumat", "Hari pertama", "Hari Arafah"], "«Pemilik hari Pembalasan»: hari ketika setiap orang menjumpai amalnya."),
"faith_014": ("Pada hari apa dalam sepekan Al-Qur'an menyeru orang beriman untuk salat berjamaah?", ["Jumat", "Senin", "Sabtu", "Minggu"], "«Apabila telah diseru untuk melaksanakan salat pada hari Jumat, maka segeralah kamu mengingat Allah.»"),
"faith_015": ("Menurut Al-Qur'an, siapa yang menjamin terpeliharanya Al-Qur'an dari segala perubahan?", ["Allah sendiri", "Hanya para malaikat", "Para ulama", "Para raja"], "«Sesungguhnya Kamilah yang menurunkan Al-Qur'an, dan pasti Kami pula yang memeliharanya.»"),
"faith_016": ("Apa yang dinyatakan Al-Qur'an tentang masuk ke dalam agama?", ["Tidak ada paksaan dalam beragama", "Dilakukan dengan sumpah", "Memerlukan saksi", "Terjadi saat dewasa"], "«Tidak ada paksaan dalam agama; sesungguhnya telah jelas jalan yang benar dari jalan yang sesat.»"),
"faith_017": ("Apa salam umat Islam, sebuah doa keselamatan?", ["Assalamu'alaikum", "Marhaban", "Shabahul khair", "Ahlan wa sahlan"], "«Assalamu'alaikum»: semoga keselamatan atasmu, dijawab dengan «wa'alaikumussalam»."),
"faith_018": ("Apa nama keyakinan akan keesaan Allah, inti ajaran Islam?", ["Tauhid", "Tafsir", "Tajwid", "Tarawih"], "Tauhid, menegaskan bahwa Allah Maha Esa tanpa sekutu, adalah dasar seluruh keimanan."),
"faith_019": ("Kitab apa yang diturunkan Allah kepada Nabi Musa?", ["Taurat", "Injil", "Zabur", "Al-Qur'an"], "«Sungguh, Kami yang menurunkan Kitab Taurat; di dalamnya ada petunjuk dan cahaya» (5:44)."),
"faith_020": ("Kitab apa yang diberikan Allah kepada Nabi Isa?", ["Injil", "Taurat", "Zabur", "Suhuf Ibrahim"], "«Kami memberikan kepadanya Kitab Injil yang di dalamnya terdapat petunjuk dan cahaya» (5:46)."),
"faith_021": ("Menurut Al-Qur'an, apa yang harus dilakukan ketika diberi salam?", ["Membalas dengan salam yang lebih baik, atau yang serupa", "Tetap diam", "Menunduk", "Hanya membalas teman"], "«Apabila kamu dihormati dengan suatu penghormatan, maka balaslah dengan yang lebih baik, atau balaslah dengan yang serupa» (4:86)."),
"faith_022": ("Surah Al-A'la menyebut «suhuf» (lembaran-lembaran) dua nabi. Siapakah keduanya?", ["Ibrahim dan Musa", "Nuh dan Hud", "Daud dan Sulaiman", "Zakaria dan Yahya"], "«Sesungguhnya ini terdapat dalam kitab-kitab yang dahulu, yaitu kitab-kitab Ibrahim dan Musa» (87:18-19)."),
"faith_023": ("Apa nama malaikat penjaga neraka yang disebut dalam Al-Qur'an?", ["Malik", "Ridwan", "Mikail", "Israfil"], "Penghuni neraka akan berseru: «Wahai Malik, biarlah Tuhanmu mematikan kami saja!» (43:77)."),
"faith_024": ("Menurut surah Al-Haqqah, berapa malaikat yang memikul Arasy Allah pada hari Kiamat?", ["Delapan", "Empat", "Dua belas", "Satu"], "«Dan pada hari itu delapan malaikat menjunjung Arasy Tuhanmu di atas mereka» (69:17)."),
"faith_025": ("Menurut Al-Qur'an, siapa yang ditugaskan mencabut nyawa saat kematian?", ["Malaikat maut", "Jibril", "Nabi", "Jin"], "«Katakanlah: Malaikat maut yang diserahi untuk mencabut nyawamu akan mematikan kamu» (32:11)."),
"faith_026": ("Dari apa para malaikat diciptakan, menurut hadis dalam Sahih Muslim?", ["Dari cahaya", "Dari api", "Dari tanah liat", "Dari air"], "«Para malaikat diciptakan dari cahaya, jin dari nyala api, dan Adam dari apa yang telah dijelaskan kepada kalian.»"),
"faith_027": ("Dari apa jin diciptakan, menurut Al-Qur'an?", ["Dari nyala api tanpa asap", "Dari cahaya", "Dari tanah liat", "Dari angin"], "«Dan Dia menciptakan jin dari nyala api tanpa asap» (55:15)."),
"faith_028": ("Siapa yang disebut Al-Qur'an sebagai musuh yang nyata bagi manusia?", ["Setan", "Para malaikat", "Hewan-hewan", "Malam"], "«Sungguh, setan itu musuh bagimu, maka perlakukanlah ia sebagai musuh» (35:6)."),
"faith_029": ("Berapa jumlah nabi yang disebut «Ulul Azmi» (yang memiliki keteguhan hati)?", ["Lima: Nuh, Ibrahim, Musa, Isa, dan Muhammad ﷺ", "Tiga", "Sepuluh", "Dua puluh lima"], "«Bersabarlah engkau seperti orang-orang yang mempunyai keteguhan hati dari rasul-rasul» (46:35); surah Asy-Syura (42:13) menyebut kelima nabi ini bersama-sama."),
"faith_030": ("Apa yang akan ditiup untuk mengumumkan hari Kebangkitan, menurut Al-Qur'an?", ["Sangkakala", "Tanduk domba", "Seruling", "Lonceng"], "«Sangkakala pun ditiup, maka matilah semua yang di langit dan di bumi… kemudian ditiup sekali lagi» (39:68)."),
"faith_031": ("Apa sebutan Al-Qur'an untuk alat penimbang amal pada hari Kiamat?", ["Timbangan (al-mawazin)", "Catatan", "Jembatan", "Sangkakala"], "«Kami akan memasang timbangan yang tepat pada hari Kiamat, maka tidak seorang pun dirugikan walau sedikit» (21:47)."),
"faith_032": ("Nama apa yang diberikan Al-Qur'an untuk tingkatan surga tertinggi yang dijanjikan bagi orang yang beriman dan beramal saleh?", ["Firdaus", "Al-Kautsar", "Ash-Shirath", "Al-A'raf"], "«Sungguh, orang yang beriman dan mengerjakan kebajikan, untuk mereka disediakan surga Firdaus sebagai tempat tinggal» (18:107)."),
"faith_033": ("Apa nama neraka yang paling sering disebut dalam Al-Qur'an?", ["Jahanam", "Firdaus", "Kautsar", "Tasnim"], "Al-Qur'an menyebut neraka «Jahanam» puluhan kali, misalnya: «Kamu akan dikumpulkan ke neraka Jahanam» (3:12)."),
"faith_034": ("Rukun iman apa yang ditegaskan ayat «Sesungguhnya Kami menciptakan segala sesuatu menurut ukuran»?", ["Iman kepada takdir (qadar)", "Iman kepada malaikat", "Iman kepada kitab-kitab", "Iman kepada para rasul"], "«Sungguh, Kami menciptakan segala sesuatu menurut ukuran (qadar)» (54:49): tidak ada yang terjadi di luar ilmu dan kehendak Allah."),
"faith_035": ("Dosa apa yang Allah nyatakan tidak akan diampuni bagi orang yang mati tanpa bertobat darinya?", ["Syirik (mempersekutukan Allah)", "Berdusta", "Kikir", "Marah"], "«Sesungguhnya Allah tidak akan mengampuni dosa syirik, dan Dia mengampuni dosa selain itu bagi siapa yang Dia kehendaki» (4:48)."),
"faith_036": ("Menurut Al-Qur'an, siapa yang dicintai Allah di antara orang-orang yang berdosa?", ["Orang yang bertobat", "Orang yang menyembunyikan dosanya", "Orang yang berputus asa", "Orang yang menyalahkan orang lain"], "«Sungguh, Allah menyukai orang yang bertobat dan menyukai orang yang menyucikan diri» (2:222)."),
"faith_037": ("Menurut surah Nuh, apa yang dibawa istigfar (memohon ampun) bagi suatu kaum?", ["Hujan lebat dan keberkahan", "Tidak ada apa-apa", "Kekeringan", "Tidur panjang"], "«Mohonlah ampunan kepada Tuhanmu, sungguh Dia Maha Pengampun, niscaya Dia akan menurunkan hujan yang lebat dari langit kepadamu» (71:10-11)."),
"faith_038": ("Apa yang dijanjikan Al-Qur'an bagi orang yang bertawakal kepada Allah?", ["Allah mencukupkan keperluannya", "Ia akan menjadi kaya", "Ia tidak akan pernah sakit", "Ia tidak perlu bekerja lagi"], "«Dan barang siapa bertawakal kepada Allah, niscaya Allah akan mencukupkan keperluannya» (65:3)."),
"faith_039": ("Apa firman Allah tentang doa dalam surah Ghafir?", ["«Berdoalah kepada-Ku, niscaya akan Aku perkenankan bagimu»", "«Berdoalah hanya di malam hari»", "«Berdoalah kepada para malaikat»", "«Doa hanya untuk para nabi»"], "«Tuhanmu berfirman: Berdoalah kepada-Ku, niscaya akan Aku perkenankan bagimu» (40:60)."),
"faith_040": ("Dengan apa, menurut Al-Qur'an, hati menjadi tenteram?", ["Dengan mengingat Allah (zikir)", "Dengan uang", "Dengan tidur", "Dengan bepergian"], "«Ingatlah, hanya dengan mengingat Allah hati menjadi tenteram» (13:28)."),
"faith_041": ("Apa salat wajib pertama dalam sehari?", ["Subuh (Fajar)", "Zuhur", "Asar", "Isya"], "Lima salat secara berurutan: Subuh, Zuhur, Asar, Magrib, dan Isya."),
"faith_042": ("Berapa rakaat salat Subuh yang wajib?", ["Dua", "Tiga", "Empat", "Satu"], "Subuh dua rakaat; Magrib tiga; Zuhur, Asar, dan Isya masing-masing empat."),
"faith_043": ("Salat wajib apa yang terdiri dari tiga rakaat?", ["Magrib", "Subuh", "Zuhur", "Isya"], "Magrib, tepat setelah matahari terbenam, adalah satu-satunya salat wajib yang tiga rakaat."),
"faith_044": ("Apa nama seruan salat yang dikumandangkan dari masjid?", ["Azan", "Khotbah", "Tasbih", "Talbiah"], "Azan dikumandangkan oleh muazin sebelum setiap dari lima salat."),
"faith_045": ("Menurut ayat wudu, sampai mana tangan harus dibasuh?", ["Sampai siku", "Sampai pergelangan tangan", "Sampai bahu", "Hanya telapak tangan"], "«Basuhlah wajahmu dan tanganmu sampai ke siku, dan sapulah kepalamu dan basuhlah kakimu sampai kedua mata kaki» (5:6)."),
"faith_046": ("Apa yang dibolehkan Al-Qur'an ketika tidak ada air untuk bersuci sebelum salat?", ["Tayamum dengan debu yang bersih", "Salat tanpa bersuci", "Menunda salat sampai esok hari", "Membasuh dengan pasir basah"], "«Lalu kamu tidak memperoleh air, maka bertayamumlah dengan debu yang baik; usaplah wajahmu dan tanganmu dengan debu itu» (5:6)."),
"faith_047": ("Apa nama ceramah yang disampaikan imam sebelum salat Jumat?", ["Khotbah", "Azan", "Ikamah", "Takbir"], "Khotbah Jumat disampaikan dalam dua bagian dari atas mimbar, sebelum salat."),
"faith_048": ("Berapa bagian dari tabungan yang telah genap setahun yang dikeluarkan seorang Muslim sebagai zakat?", ["2,5%", "10%", "25%", "1%"], "Zakat harta simpanan adalah seperempat dari sepersepuluh, yaitu 2,5%, setelah mencapai nisab selama satu tahun hijriah."),
"faith_049": ("Sedekah khusus apa yang wajib di akhir Ramadan, sebelum salat Id?", ["Zakat fitrah", "Zakat emas", "Khumus", "Kafarat"], "Nabi ﷺ mewajibkan zakat fitrah, satu sha' kurma atau gandum, bagi setiap Muslim, tua maupun muda."),
"faith_050": ("Menurut Al-Qur'an, dari kapan sampai kapan puasa harian Ramadan berlangsung?", ["Dari fajar sampai malam", "Dari tengah hari sampai petang", "Dari matahari terbit sampai tengah hari", "Sepanjang siang dan malam"], "«Makan dan minumlah hingga jelas bagimu benang putih dari benang hitam, yaitu fajar, kemudian sempurnakanlah puasa sampai malam» (2:187)."),
"faith_051": ("Apa nama makan sebelum fajar bagi orang yang akan berpuasa?", ["Sahur", "Buka puasa (iftar)", "Walimah", "Akikah"], "Nabi ﷺ bersabda: «Bersahurlah kalian, karena dalam sahur ada keberkahan.»"),
"faith_052": ("Apa nama makan yang membatalkan puasa saat matahari terbenam?", ["Buka puasa (iftar)", "Sahur", "Tarawih", "Tahajud"], "Buka puasa dilakukan begitu matahari terbenam, pada waktu salat Magrib."),
"faith_053": ("Berapa hari raya (Id) dalam Islam setiap tahun?", ["Dua: Idulfitri dan Iduladha", "Hanya satu", "Empat", "Dua belas"], "Idulfitri menutup bulan Ramadan; Iduladha jatuh pada 10 Zulhijah, selama musim haji."),
"faith_054": ("Peristiwa apa yang diperingati Iduladha?", ["Pengorbanan Ibrahim yang ditebus dengan seekor domba", "Kelahiran Nabi ﷺ", "Perang Badar", "Turunnya Al-Qur'an"], "Saat siap menyembelih putranya, Ibrahim melihatnya ditebus: «Kami tebus anak itu dengan seekor sembelihan yang besar» (37:107)."),
"faith_055": ("Pada bulan apa dalam kalender Islam ibadah haji dilaksanakan?", ["Zulhijah", "Ramadan", "Muharam", "Rajab"], "Haji dilaksanakan dari 8 hingga 13 Zulhijah, bulan kedua belas dan terakhir dalam tahun hijriah."),
"faith_056": ("Pada tanggal berapa Zulhijah para jemaah haji wukuf di padang Arafah?", ["Tanggal 9", "Tanggal 1", "Tanggal 10", "Tanggal 27"], "Wukuf di Arafah pada 9 Zulhijah adalah rukun utama haji; Iduladha jatuh keesokan harinya."),
"faith_057": ("Berapa putaran mengelilingi Ka'bah dalam satu tawaf?", ["Tujuh", "Tiga", "Lima", "Sepuluh"], "Tawaf adalah tujuh putaran mengelilingi Ka'bah, berlawanan arah jarum jam, dimulai dari Hajar Aswad."),
"faith_058": ("Berapa kali perjalanan antara Shafa dan Marwah dalam sa'i?", ["Tujuh", "Dua", "Empat", "Dua belas"], "Sa'i mengenang pencarian air oleh Hajar untuk Ismail: tujuh kali, dari Shafa ke Marwah dan sebaliknya, setiap arah dihitung."),
"faith_059": ("Apa nama keadaan suci yang dimasuki jemaah haji, dengan dua kain putihnya?", ["Ihram", "Tawaf", "Wukuf", "Talbiah"], "Dalam ihram, laki-laki memakai dua kain tanpa jahitan dan jemaah menahan diri dari wewangian, berburu, dan bertengkar."),
"faith_060": ("Dengan kata apa talbiah, yang diulang jemaah dalam perjalanan ke Makkah, dimulai?", ["«Labbaikallahumma labbaik» (Aku penuhi panggilan-Mu, ya Allah)", "«Allahu akbar»", "«Subhanallah»", "«Alhamdulillah»"], "Talbiah Nabi ﷺ adalah: «Labbaikallahumma labbaik, labbaika la syarika laka labbaik…»"),
"faith_061": ("Apa yang dilakukan jemaah haji di Mina ketika melempar kerikil ke tiga tugu?", ["Melontar jumrah", "Tawaf", "Sa'i", "Wukuf di Arafah"], "Melontar jumrah mengenang Ibrahim yang mengusir setan dengan batu; dilakukan di Mina pada hari-hari Id."),
"faith_062": ("Di mana letak Hajar Aswad (Batu Hitam)?", ["Di salah satu sudut Ka'bah", "Di Jabal Arafah", "Di Madinah", "Di puncak Jabal Hira"], "Terpasang di sudut timur Ka'bah, Hajar Aswad menandai titik awal setiap putaran tawaf."),
"faith_063": ("Apa nama kain hitam besar yang menutupi Ka'bah?", ["Kiswah", "Hijab", "Mimbar", "Mihrab"], "Kiswah, yang disulam dengan ayat-ayat berbenang emas, diganti setiap tahun pada musim haji."),
"faith_064": ("Apa nama ziarah «kecil» ke Makkah yang dapat dilakukan kapan saja sepanjang tahun?", ["Umrah", "Haji", "Hijrah", "Ziarah"], "Umrah terdiri dari ihram, tawaf, dan sa'i; berbeda dengan haji, umrah tidak terikat pada bulan tertentu."),
"faith_065": ("Apa arti nama Allah «Al-Khaliq»?", ["Yang Maha Pencipta", "Yang Maha Pengampun", "Yang Maha Pemberi Rezeki", "Yang Maha Merajai"], "«Dialah Allah Yang Menciptakan (Al-Khaliq), Yang Mengadakan, Yang Membentuk Rupa» (59:24)."),
"faith_066": ("Apa arti nama Allah «Al-Ghafur»?", ["Yang Maha Pengampun", "Yang Maha Pencipta", "Yang Mahaperkasa", "Yang Maha Pemurah"], "«Janganlah kamu berputus asa dari rahmat Allah… Dialah Yang Maha Pengampun (Al-Ghafur), Maha Penyayang» (39:53)."),
"faith_067": ("Apa arti dua nama Allah «As-Sami'» dan «Al-Bashir»?", ["Yang Maha Mendengar dan Yang Maha Melihat", "Yang Merajai dan Yang Menghakimi", "Yang Mencipta dan Yang Memberi Rezeki", "Yang Awal dan Yang Akhir"], "Ayat Isra ditutup dengan: «Dialah Yang Maha Mendengar (As-Sami'), Maha Melihat (Al-Bashir)» (17:1)."),
"faith_068": ("Apa arti «Ash-Shamad», nama Allah dalam surah Al-Ikhlas?", ["Tempat bergantung segala sesuatu, yang tidak bergantung pada apa pun", "Yang mengampuni", "Yang mendengar", "Yang mencipta"], "«Allahush-Shamad» (112:2): Penguasa mutlak yang kepada-Nya semua makhluk bergantung untuk kebutuhan mereka."),
"faith_069": ("Dua nama Allah apa yang membuka Ayat Kursi, tepat setelah «Allah, tidak ada tuhan selain Dia»?", ["Al-Hayy dan Al-Qayyum (Yang Mahahidup, Yang Terus-menerus Mengurus)", "Ar-Rahman dan Ar-Rahim", "Al-Malik dan Al-Quddus", "Al-'Aziz dan Al-Hakim"], "«Allah, tidak ada tuhan selain Dia, Yang Mahahidup, Yang Terus-menerus Mengurus makhluk-Nya» (2:255)."),
"faith_070": ("Apa arti nama Allah «Ar-Razzaq»?", ["Yang Maha Pemberi Rezeki", "Yang Maha Pengampun", "Yang Mahaadil", "Yang Mahalembut"], "«Sungguh Allah, Dialah Pemberi rezeki (Ar-Razzaq) yang mempunyai kekuatan lagi sangat kukuh» (51:58)."),
}
